import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.iXqqCa-C.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1793029602000}'),r={name:"guide/faq.md"};function o(s,a,d,n,h,p){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="aliya-web-提示「刚刚聊的有点累了-休息一下马上回复」" tabindex="-1">Aliya Web 提示「刚刚聊的有点累了，休息一下马上回复」？ <a class="header-anchor" href="#aliya-web-提示「刚刚聊的有点累了-休息一下马上回复」" aria-label="Permalink to &quot;Aliya Web 提示「刚刚聊的有点累了，休息一下马上回复」？&quot;">​</a></h2><p>这是临时限流，稍等片刻便会自行恢复。出现该回复时发送的对应消息不会被记录和保留。若频繁出现，可以<a href="#遇到-bug-或异常怎么反馈">向我们反馈</a>。</p><h2 id="切换对话时提示-429-错误" tabindex="-1">切换对话时提示 429 错误？ <a class="header-anchor" href="#切换对话时提示-429-错误" aria-label="Permalink to &quot;切换对话时提示 429 错误？&quot;">​</a></h2><p>如果你在 Aliya Web 中进行切换对话等操作时提示 <strong>429 错误</strong>，并且 Misskey 端也提示 &quot;Rate limit exceeded&quot;，说明触发了服务器限流。等候一段时间后即可恢复使用。</p><h2 id="api-token-泄露了怎么办" tabindex="-1">API Token 泄露了怎么办？ <a class="header-anchor" href="#api-token-泄露了怎么办" aria-label="Permalink to &quot;API Token 泄露了怎么办？&quot;">​</a></h2><p>立即删除泄露的令牌，防止未经授权的登录：</p><ol><li>访问 Misskey 主页，依次点击 <strong>设置 – 连接服务 – 管理访问令牌</strong>。</li><li>删除对应的令牌。</li><li>重新生成令牌并<a href="/guide/third-party#api-登录">重新登录</a>。</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>api token 具有账户的完整访问权限，请像对待密码一样保管它。</p></div><h2 id="遇到-bug-或异常怎么反馈" tabindex="-1">遇到 bug 或异常怎么反馈？ <a class="header-anchor" href="#遇到-bug-或异常怎么反馈" aria-label="Permalink to &quot;遇到 bug 或异常怎么反馈？&quot;">​</a></h2><p>通过下方任一方式<a href="#联系项目组">联系项目组</a>，附上出现问题的截图和操作步骤。</p><h2 id="联系项目组" tabindex="-1">联系项目组 <a class="header-anchor" href="#联系项目组" aria-label="Permalink to &quot;联系项目组&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>地址</th><th>说明</th></tr></thead><tbody><tr><td>官方 Q 群</td><td>519308434</td><td>响应较快，适合日常问题与 bug 反馈</td></tr><tr><td>官方邮箱</td><td><a href="mailto:help@liminalselves.top" target="_blank" rel="noreferrer">help@liminalselves.top</a></td><td>处理速度较慢，适合报备、举报、投诉、申诉等社区事务</td></tr></tbody></table><p>相关地址：</p><ul><li>阈界人格社区：<a href="https://misskey.liminalselves.top/" target="_blank" rel="noreferrer">https://misskey.liminalselves.top/</a></li><li>Aliya Web：<a href="https://aliya.liminalselves.top" target="_blank" rel="noreferrer">https://aliya.liminalselves.top</a></li></ul>',15)])])}const c=e(r,[["render",o]]);export{u as __pageData,c as default};
